#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

#define MAXV 8   /* the original binary limits vertices to 8 */

int main(int argc, char **argv)
{
    /* --------------------------------------------------------------
     * 1. Basic command‑line shape validation
     * -------------------------------------------------------------- */
    if (argc < 3) {                     /* need at least N and M */
        puts("INVALID_INPUT");
        return 1;
    }

    /* After the program name the number of arguments must be even
       (pairs of vertices for each edge). */
    if ( ((argc - 1) & 1) != 0 ) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* --------------------------------------------------------------
     * 2. Parse N (vertices) and M (edges)
     * -------------------------------------------------------------- */
    long n = strtol(argv[1], NULL, 10);
    long m = strtol(argv[2], NULL, 10);

    if (n < 0 || n > MAXV) {
        puts("INVALID_INPUT");
        return 1;
    }
    if (m < 0) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* Exactly 2*m additional arguments must be present for the edges. */
    if (argc != 3 + 2 * m) {
        puts("INVALID_INPUT");
        return 1;
    }

    /* --------------------------------------------------------------
     * 3. Initialise graph structures
     * -------------------------------------------------------------- */
    int adj[MAXV][MAXV] = {0};   /* adjacency matrix */
    int indeg[MAXV] = {0};       /* indegree of each vertex */
    bool done[MAXV] = {0};       /* whether a vertex has already been output */

    /* --------------------------------------------------------------
     * 4. Read the edges
     * -------------------------------------------------------------- */
    for (long i = 0; i < m; ++i) {
        long u = strtol(argv[3 + 2 * i],     NULL, 10);
        long v = strtol(argv[3 + 2 * i + 1], NULL, 10);

        if (u < 0 || u >= n || v < 0 || v >= n) {
            puts("INVALID_INPUT");
            return 1;
        }

        /* Record the edge; duplicate edges are ignored for indegree count. */
        if (!adj[u][v]) {
            adj[u][v] = 1;
            indeg[v]++;               /* increase indegree of destination */
        }
    }

    /* --------------------------------------------------------------
     * 5. Kahn’s topological sort
     * -------------------------------------------------------------- */
    int order[MAXV];
    int out_idx = 0;

    while (out_idx < n) {
        int v = -1;

        /* Find a vertex with indegree 0 that hasn't been output yet. */
        for (int i = 0; i < n; ++i) {
            if (!done[i] && indeg[i] == 0) {
                v = i;
                break;
            }
        }

        if (v == -1) {               /* no such vertex → cycle */
            puts("CYCLE");
            return 1;
        }

        order[out_idx++] = v;
        done[v] = true;

        /* Decrease indegree of all neighbours of v. */
        for (int j = 0; j < n; ++j) {
            if (adj[v][j]) {
                indeg[j]--;
            }
        }
    }

    /* --------------------------------------------------------------
     * 6. Print the resulting order
     * -------------------------------------------------------------- */
    for (int i = 0; i < n; ++i) {
        printf("%d", order[i]);
        if (i + 1 < n) putchar(' ');
    }
    putchar('\n');

    return 0;
}
